<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT * FROM matters WHERE id=?');$stmt->execute([$id]);$matter=$stmt->fetch();if(!$matter){http_response_code(404);exit('Matter not found.');}$clients=$pdo->query('SELECT id,name,client_reference FROM clients ORDER BY name')->fetchAll();$error='';
require_once __DIR__ . '/legal_library.php';
if($_SERVER['REQUEST_METHOD']==='POST'){aep_validate_csrf();$client=(int)($_POST['client_id']??0);$area=aep_post_string('practice_area',100);$subject=aep_post_string('subject',300);if(!$client||$area===''||$subject===''){$error='Client, practice area, and subject are required.';}else{$pdo->prepare('UPDATE matters SET client_id=?,practice_area=?,subject=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$client,$area,$subject,aep_valid_status(aep_post_string('status',20),['open','active','closed'],'open'),$id]);aep_log_activity($pdo,'Matters','Updated '.$matter['matter_reference']);header('Location:matter_view.php?id='.$id);exit;}}
$pageTitle='Edit Matter | AEP';$activeNav='matters';require __DIR__.'/includes/header.php';?><div class="card" style="max-width:820px;margin:auto"><h1>Edit Matter</h1><?php if($error):?><p style="color:#b42318"><?php echo aep_h($error);?></p><?php endif;?><form method="post" class="grid grid-2" style="margin-top:18px"><?php echo aep_csrf_field();?><div><label>Client *</label><select required name="client_id"><?php foreach($clients as $client):?><option value="<?php echo $client['id'];?>" <?php echo (int)($matter['client_id'])===(int)$client['id']?'selected':'';?>><?php echo aep_h($client['name'].' — '.$client['client_reference']);?></option><?php endforeach;?></select></div><div><label>Practice area *</label><select required name="practice_area"><?php foreach(aep_domain_profiles() as $profile):?><option <?php echo $matter['practice_area']===$profile['label']?'selected':'';?> value="<?php echo aep_h($profile['label']);?>"><?php echo aep_h($profile['label']);?></option><?php endforeach;?></select></div><div><label>Subject *</label><input required name="subject" value="<?php echo aep_h($matter['subject']);?>"></div><div><label>Status</label><select name="status"><?php foreach(['open','active','closed'] as $status):?><option <?php echo $matter['status']===$status?'selected':'';?> value="<?php echo $status;?>"><?php echo ucfirst($status);?></option><?php endforeach;?></select></div><div class="actions"><button class="btn">Save changes</button><a class="btn secondary" href="matter_view.php?id=<?php echo $id;?>">Cancel</a></div></form></div><?php require __DIR__.'/includes/footer.php';?>
